// Reload refetches the object from the database
// using the primary keys with an executor.
func (o *Pais) Reload(ctx context.Context, exec boil.ContextExecutor) error {
	ret, err := FindPais(ctx, exec, o.PaiID)
	if err != nil {
		return err
	}

	*o = *ret
	return nil
}

// ReloadAll refetches every row with matching primary key column values
// and overwrites the original object slice with the newly updated slice.
func (o *PaisSlice) ReloadAll(ctx context.Context, exec boil.ContextExecutor) error {
	if o == nil || len(*o) == 0 {
		return nil
	}

	slice := PaisSlice{}
	var args []interface{}
	for _, obj := range *o {
		pkeyArgs := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(obj)), paisPrimaryKeyMapping)
		args = append(args, pkeyArgs...)
	}

	sql := "SELECT `pais`.* FROM `pais` WHERE " +
		strmangle.WhereClauseRepeated(string(dialect.LQ), string(dialect.RQ), 0, paisPrimaryKeyColumns, len(*o))

	q := queries.Raw(sql, args...)

	err := q.Bind(ctx, exec, &slice)
	if err != nil {
		return errors.Wrap(err, "models: unable to reload all in PaisSlice")
	}

	*o = slice

	return nil
}

// PaisExists checks if the Pais row exists.
func PaisExists(ctx context.Context, exec boil.ContextExecutor, paiID int) (bool, error) {
	var exists bool
	sql := "select exists(select 1 from `pais` where `pai_id`=? limit 1)"

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, sql)
		fmt.Fprintln(writer, paiID)
	}
	row := exec.QueryRowContext(ctx, sql, paiID)

	err := row.Scan(&exists)
	if err != nil {
		return false, errors.Wrap(err, "models: unable to check if pais exists")
	}

	return exists, nil
}

// Exists checks if the Pais row exists.
func (o *Pais) Exists(ctx context.Context, exec boil.ContextExecutor) (bool, error) {
	return PaisExists(ctx, exec, o.PaiID)
}
